<?php
namespace App\Http\Controllers;
use App\Exports\TrainingAnalyticsExport;use App\Services\TrainingMatrixService;use Illuminate\Http\Request;use Maatwebsite\Excel\Facades\Excel;
class TrainingMatrixController extends Controller{public function index(Request$r,TrainingMatrixService$s){$employees=$s->paginate($r->user()->company_id,$r->only('job','area','employee','state'));return view('training.matrix.index',compact('employees'));}public function export(Request$r,TrainingMatrixService$s){$employees=$s->paginate($r->user()->company_id,array_merge($r->only('job','area','employee','state'),['per_page'=>500]));$rows=[];foreach($employees as$employee)foreach($employee->training_route as$route)$rows[]=[ $employee->nombre_completo,$employee->cargo,$employee->area_departamento,$route['requirement']->topic->name,$route['status'],$route['expires']?->format('Y-m-d')];return Excel::download(new TrainingAnalyticsExport($rows,['Trabajador','Cargo','Área','Requisito','Estado','Vence'],'Matriz'),'matriz-formacion.xlsx');}}
